/* v0.18.2: one QR-column alignment rule and a quieter global header.
   This replaces the detached full-width confirmation layout; no runtime state changes. */
.header-inner{column-gap:20px;row-gap:10px}
.brand-mark{width:39px;height:39px}
.brand-name{font-size:21.5px;line-height:1.2}
.brand{gap:10px}
.header-actions{display:flex;flex:0 1 auto;align-items:center;justify-content:flex-end;gap:16px;min-width:0;max-width:100%;margin-inline-start:auto}
.header-actions .release-status{display:block;flex:0 1 auto;min-width:0;margin:0;font-size:12px;line-height:1.5}
.header-actions .release-status a{display:block;color:#aebdcc;font-size:12px;text-decoration:none;overflow-wrap:anywhere}
.header-actions .release-status a:hover{text-decoration:underline;text-underline-offset:3px}
.release-status .release-version{margin:0;white-space:normal;overflow-wrap:anywhere}
.release-status .release-version::before{content:' · ';white-space:pre}
.header-actions .help-control{display:grid;place-items:center;flex:0 0 44px;width:44px;min-width:44px;min-height:44px;padding:0;border:1px solid #647987;border-radius:50%;background:#ffffff04;color:#e3c08f;text-decoration:none;line-height:1;font-size:20px;font-weight:600}
.help-control:hover,.help-control[aria-current=page]{background:#ffffff0c;border-color:#b79568}
.help-control:focus-visible{outline:2px solid var(--orange);outline-offset:4px}
.seed-layout{grid-template-columns:minmax(0,1fr) min(42%,376px);gap:28px;align-items:start}
.seed-layout.seed-layout-expanded{grid-template-columns:minmax(0,1fr) min(50%,456px)}
.seed-layout .seed-scan,.seed-layout .seed-scan.seed-expanded{display:block;grid-column:auto;width:100%;max-width:none;min-width:0;margin:0;padding:16px;border:1px solid var(--line);border-radius:16px;background:#0c1923;text-align:left;justify-self:end}
.seed-layout .seed-scan .qr-column,.seed-layout .seed-scan.seed-expanded .qr-column{width:100%;max-width:none;margin:0;text-align:left;display:block}
.seed-layout .seed-scan .qr-frame,.seed-layout .seed-scan.seed-expanded .qr-frame{width:100%;max-width:none;margin:0}
.seed-layout .wallet-confirmation{display:block;width:100%;max-width:none;margin:14px 0 0;padding:0;border:0;border-radius:0;background:none}
.wallet-confirmation-copy{min-width:0}
.wallet-confirmation .wallet-fingerprint{justify-content:space-between;gap:5px 10px}
.wallet-confirmation #wallet-compare-hint{margin:8px 0 0;max-width:none;font-size:12px;line-height:1.6}
.wallet-confirmation .wallet-confirmation-actions{display:flex;align-items:stretch;justify-content:flex-end;width:100%;margin:14px 0 0;gap:8px;flex-wrap:wrap}
.wallet-confirmation-actions>.button,.wallet-confirmation-actions .seed-qr-actions>.button{margin:0;min-height:44px;max-width:100%;padding:10px 12px;font-size:13px;line-height:1.4}
.wallet-confirmation-actions .seed-qr-actions>.button{flex:1 1 118px}
.wallet-confirmation-actions>#wallet-loaded{flex:1 1 190px}
/* The response QR's save/copy controls follow its edges too. */
.sign-layout>.qr-column .qr-format-control{width:100%;max-width:none;}
.sign-layout>.qr-column .psbt-actions{display:flex;width:100%;max-width:100%;margin:10px 0 0;gap:8px;justify-content:flex-end;align-items:stretch}
.sign-layout>.qr-column .psbt-actions>.button:first-child{flex:1 1 auto;min-height:44px}
.sign-layout>.qr-column .psbt-actions>.icon-button{width:44px;min-width:44px;height:44px;min-height:44px;flex:0 0 44px}
